// Generated by the compiler (znight generate, vite build, bun test): every provider, its
// dependencies, the route table and the OpenAPI operations. Only this file and the tests import it.
import { createApplication } from './.znight/container.generated.js'
import { plugins } from './app.js'

/**
 * In production, serve the document written by `znight build` next to the bundle
 * (`dist/openapi.json`, equal to the committed `openapi.json`) instead of assembling it at boot.
 */
const document = process.env.NODE_ENV === 'production' ? { file: new URL('./openapi.json', import.meta.url) } : 'build'

const app = await createApplication({
  // observability, configuration, HTTP and OpenAPI, shared with the tests (src/app.ts)
  plugins: plugins({ openapi: { document } }),
  // SIGINT / SIGTERM stop the application gracefully: the HTTP server stops accepting connections
  // and drains in-flight requests (4 s), then providers stop. Keep `timeoutMs` below the grace
  // period of your platform (Kubernetes: 30 s, `docker stop`: 10 s).
  shutdown: { timeoutMs: 8_000, hookTimeoutMs: 5_000 },
})

await app.start()
